   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="请原谅我得用这种老电影一样的方式为你传送指令，但你所在的位置已经进入了监听网络的范围，这种古老的方法反而可以欺骗它们的耳朵。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [31]={next_id=32, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="请看向你的正前方，那座华丽的庄园，就是身为十字党党魁的，修奈泽尔·冯·黑斯廷斯公爵的公爵府邸“维斯林堡”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥莉维娅抬头，朝着字条里说的方向看去，豁然开朗的空间里座落着富丽堂皇的庄园。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在寸土寸金的要塞都市里，这座庄园足足有六七个足球场那那么大，可见庄园主人的实力有多么强悍。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="修奈泽尔·冯·黑斯廷斯……", msg_color="", msg_size=0, talker="奥莉维娅", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4108", 0, 0, -128, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥莉维娅想起了自己的老师雷奥妮，黑斯廷斯家族是克罗瓦德自百年战争前就声名显赫的大贵族，但完全无法让人想到她也是这个家族中的一员，甚至她本人就是公爵的千金。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凡事亲力亲为，与自己的士兵和学生一同席地而眠，正因为雷奥妮的身体力行，奥莉维娅才会选择她作为自己的老师。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="老师她……应该很讨厌自己的家族吧，从来没听过她讲自己家族的事情。", msg_color="", msg_size=0, talker="奥莉维娅", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4108", 0, 0, -128, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥莉维娅出神了一会儿，直到瓦格纳啄了啄手，她才回过神来，继续读手里的字条。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
