   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我知道让你这个先锋骑兵来做这种密探活儿属实有些委屈，但现在十字党对我势力的绞杀正在愈演愈烈，我实在是没有更多的线人可以接近这场密会了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
