   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="奥莉维娅一直不是很喜欢科林城，相比起满是矿洞和老旧的蒸汽工厂、还能享受到一定日子太阳的老家哈拉罗，科林城就是座除了繁荣、贵气和权力以外一无是处的大铁坨子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_704.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
